package aggregator_test

import (
	"encoding/base64"
	"testing"

	"github.com/skip-mev/connect/v2/abci/strategies/codec"
	"github.com/stretchr/testify/require"
)

func TestDecodeVoteExtensionTx(t *testing.T) {
	encoded := ""

	bz, err := base64.StdEncoding.DecodeString(encoded)
	require.NoError(t, err)

	// Decode ExtendedCommitInfo with ZStd compression
	commitCodec := codec.NewCompressionExtendedCommitCodec(
		codec.NewDefaultExtendedCommitCodec(),
		codec.NewZStdCompressor(),
	)

	eci, err := commitCodec.Decode(bz)
	require.NoError(t, err)
	require.NotEmpty(t, eci.Votes)

	t.Logf("Decoded ExtendedCommitInfo: %+v", eci)

	// Decode VoteExtensions with ZLib compression
	veCodec := codec.NewCompressionVoteExtensionCodec(
		codec.NewDefaultVoteExtensionCodec(),
		codec.NewZLibCompressor(),
	)

	for i, vote := range eci.Votes {
		if len(vote.VoteExtension) > 0 {
			ve, err := veCodec.Decode(vote.VoteExtension)
			require.NoError(t, err)
			require.NotEmpty(t, ve.Prices)
			t.Logf("Vote %d: Decoded VoteExtension: %+v", i, ve)
		}
	}
}
